'use client';

import { useEffect, useMemo, useRef, useState } from 'react';

import {
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import {
  PRESS_LEAD_MS,
  pressedSolidOf,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import { Button } from '@/registry/ndeko/ui/button';

import { DemoBand } from './_parts/demo-band';
import { AT_REST, NEXT_FRAME } from './_parts/frame-loop';
import { DEFAULT_HUE } from './_parts/hue';
import { clamp, smoothstep, towards } from './_parts/math';
import { randomOf } from './_parts/seeded';
import type { Scene } from './_parts/stage';
import { StageCanvas, type StageHandle } from './_parts/stage-canvas';
import { wipeSurface, type Inks, type Surface } from './_parts/surface';

const DEFAULT_SQUARE = 4;

const DEFAULT_GAP = 4;

/** A square outside the word never gets darker than this: the grid stays a texture behind text. */
const DEFAULT_CEILING = 0.3;

/** A square of the word sits between these two, so the word reads by opacity alone. */
const WORD_FLOOR = 0.55;

const WORD_CEILING = 0.9;

const FLICKER_MS = 520;

/** The share of the squares that start a flicker each second: a few at a time. */
const FLICKER_RATE = 0.04;

/** A new word surfaces over this long: each of its squares starts at its own moment. */
const WORD_SPREAD_MS = 700;

/** The word is set this tall, as a share of the rows, and narrowed to fit this share of the columns. */
const WORD_HEIGHT_SHARE = 0.44;

const WORD_WIDTH_SHARE = 0.86;

const WORD_WEIGHT = 600;

/** How much ink a pixel of the word needs for its square to belong to the word, out of 255. */
const INK_THRESHOLD = 110;

const ALPHA_OFFSET = 3;

const CHANNELS = 4;

/** Below this a square is not drawn at all. */
const FAINT = 0.004;

const SEED = 20261112;

const NO_INKS: Inks = { hue: 'transparent', line: 'transparent' };

type GridOptions = {
  size: number;
  gap: number;
  maxOpacity: number;
  wordAt: number;
};

type Grid = {
  square: number;
  gap: number;
  pitch: number;
  /** The margin wiped around a square, so no rim is left on a screen of uneven density. */
  bleed: number;
  ceiling: number;
  wordAt: number;
  isStill: boolean;
  inks: Inks;
  family: string;
  columns: number;
  rows: number;
  offsetX: number;
  offsetY: number;
  level: Float32Array;
  from: Float32Array;
  to: Float32Array;
  startsAt: Float64Array;
  isBusy: Uint8Array;
  /** The squares in the middle of a flicker, packed at the start of the list. */
  busy: Int32Array;
  busyCount: number;
  isWord: Uint8Array;
  word: string;
  hasShownWord: boolean;
  /** Flickers owed by the rate and not started yet: the rate rarely gives a whole number a frame. */
  owed: number;
  random: () => number;
};

function wholePixelsOf(length: number) {
  const rounded = Math.round(length);
  return Math.max(1, rounded);
}

function gridOf({ size, gap, maxOpacity, wordAt }: GridOptions): Grid {
  const square = wholePixelsOf(size);
  const space = wholePixelsOf(gap);
  const halfSpace = space / 2;
  return {
    square,
    gap: space,
    pitch: square + space,
    bleed: Math.min(1, halfSpace),
    ceiling: clamp(maxOpacity, 0, 1),
    wordAt: clamp(wordAt, 0, 1),
    isStill: false,
    inks: NO_INKS,
    family: 'sans-serif',
    columns: 0,
    rows: 0,
    offsetX: 0,
    offsetY: 0,
    level: new Float32Array(0),
    from: new Float32Array(0),
    to: new Float32Array(0),
    startsAt: new Float64Array(0),
    isBusy: new Uint8Array(0),
    busy: new Int32Array(0),
    busyCount: 0,
    isWord: new Uint8Array(0),
    word: '',
    hasShownWord: false,
    owed: 0,
    random: randomOf(SEED),
  };
}

/** A level for one square: high inside the word, low and mostly dim outside it. */
function levelFor(grid: Grid, index: number) {
  const roll = grid.random();
  const isInWord = grid.isWord[index] === 1;
  if (isInWord) {
    const span = WORD_CEILING - WORD_FLOOR;
    const lift = roll * span;
    return WORD_FLOOR + lift;
  }
  const dim = roll * roll;
  return dim * grid.ceiling;
}

function fontOf(grid: Grid, pixels: number) {
  return `${WORD_WEIGHT} ${pixels}px ${grid.family}`;
}

/**
 * The word, as one pixel a square: it is drawn as text on a sheet as large as the grid, in the
 * face the canvas inherits, and a square belongs to the word where its pixel took enough ink.
 */
function readWord(grid: Grid) {
  const { columns, rows, word } = grid;
  const count = columns * rows;
  const mask = new Uint8Array(count);
  const hasNoWord = word === '';
  if (hasNoWord || count === 0) {
    return mask;
  }
  const sheet = document.createElement('canvas');
  sheet.width = columns;
  sheet.height = rows;
  const pen = sheet.getContext('2d');
  if (!pen) {
    return mask;
  }
  const tallest = rows * WORD_HEIGHT_SHARE;
  const widest = columns * WORD_WIDTH_SHARE;
  const centreX = columns / 2;
  const centreY = rows * grid.wordAt;
  pen.font = fontOf(grid, tallest);
  const measured = pen.measureText(word).width;
  const width = Math.max(1, measured);
  const room = widest / width;
  const fit = Math.min(1, room);
  const fitted = tallest * fit;
  pen.font = fontOf(grid, fitted);
  pen.textAlign = 'center';
  pen.textBaseline = 'middle';
  pen.fillText(word, centreX, centreY);
  const pixels = pen.getImageData(0, 0, columns, rows).data;
  for (let index = 0; index < count; index += 1) {
    const firstChannel = index * CHANNELS;
    const alphaAt = firstChannel + ALPHA_OFFSET;
    const hasInk = pixels[alphaAt] > INK_THRESHOLD;
    mask[index] = Number(hasInk);
  }
  return mask;
}

/** Starts a square on its way to a new level. A square already on its way heads for the new one. */
function beginFlicker(grid: Grid, index: number, startsAt: number) {
  grid.from[index] = grid.level[index];
  grid.to[index] = levelFor(grid, index);
  grid.startsAt[index] = startsAt;
  const isListed = grid.isBusy[index] === 1;
  if (isListed) {
    return;
  }
  grid.isBusy[index] = 1;
  grid.busy[grid.busyCount] = index;
  grid.busyCount += 1;
}

function settleLevels(grid: Grid) {
  for (let index = 0; index < grid.level.length; index += 1) {
    grid.level[index] = levelFor(grid, index);
  }
  grid.busyCount = 0;
  grid.isBusy.fill(0);
}

/**
 * The squares that enter or leave the word change level. The first word, and any word under
 * reduced motion, is there at once. A later word surfaces: each square starts at its own moment.
 */
function takeWord(grid: Grid, now: number) {
  const mask = readWord(grid);
  const isAtOnce = grid.isStill || !grid.hasShownWord;
  grid.hasShownWord = true;
  for (let index = 0; index < mask.length; index += 1) {
    const hasChanged = mask[index] !== grid.isWord[index];
    grid.isWord[index] = mask[index];
    if (hasChanged && isAtOnce) {
      grid.level[index] = levelFor(grid, index);
    }
    if (hasChanged && !isAtOnce) {
      const delay = grid.random() * WORD_SPREAD_MS;
      const startsAt = now + delay;
      beginFlicker(grid, index, startsAt);
    }
  }
}

function countAlong(length: number, grid: Grid) {
  const roomy = length + grid.gap;
  const count = Math.floor(roomy / grid.pitch);
  return Math.max(0, count);
}

/** The grid is centred in the box on whole pixels, so every square has crisp edges. */
function offsetOf(length: number, count: number, grid: Grid) {
  const pitched = count * grid.pitch;
  const spanned = pitched - grid.gap;
  const spare = length - spanned;
  return Math.floor(spare / 2);
}

function layGrid(grid: Grid, surface: Surface, isStill: boolean) {
  const columns = countAlong(surface.width, grid);
  const rows = countAlong(surface.height, grid);
  const count = columns * rows;
  grid.columns = columns;
  grid.rows = rows;
  grid.offsetX = offsetOf(surface.width, columns, grid);
  grid.offsetY = offsetOf(surface.height, rows, grid);
  grid.isStill = isStill;
  grid.family = getComputedStyle(surface.canvas).fontFamily;
  grid.level = new Float32Array(count);
  grid.from = new Float32Array(count);
  grid.to = new Float32Array(count);
  grid.startsAt = new Float64Array(count);
  grid.isBusy = new Uint8Array(count);
  grid.busy = new Int32Array(count);
  grid.busyCount = 0;
  grid.owed = 0;
  grid.random = randomOf(SEED);
  grid.isWord = readWord(grid);
  settleLevels(grid);
}

function paintSquare(pen: CanvasRenderingContext2D, grid: Grid, index: number) {
  const column = index % grid.columns;
  const row = Math.floor(index / grid.columns);
  const across = column * grid.pitch;
  const down = row * grid.pitch;
  const x = grid.offsetX + across;
  const y = grid.offsetY + down;
  const rim = grid.bleed * 2;
  const wiped = grid.square + rim;
  const wipedX = x - grid.bleed;
  const wipedY = y - grid.bleed;
  pen.clearRect(wipedX, wipedY, wiped, wiped);
  const level = grid.level[index];
  if (level < FAINT) {
    return;
  }
  pen.globalAlpha = level;
  pen.fillRect(x, y, grid.square, grid.square);
}

function drawGrid(grid: Grid, surface: Surface) {
  const { pen } = surface;
  wipeSurface(surface);
  pen.fillStyle = grid.inks.hue;
  for (let index = 0; index < grid.level.length; index += 1) {
    paintSquare(pen, grid, index);
  }
}

/** A few squares, picked at random, start towards a new level. One already on its way is left alone. */
function startFlickers(grid: Grid, seconds: number, now: number) {
  const count = grid.level.length;
  const perSecond = count * FLICKER_RATE;
  grid.owed += perSecond * seconds;
  while (grid.owed >= 1) {
    grid.owed -= 1;
    const roll = grid.random() * count;
    const pick = Math.floor(roll);
    const isFree = grid.isBusy[pick] === 0;
    if (isFree) {
      beginFlicker(grid, pick, now);
    }
  }
}

/** Moves one square along its flicker and draws it. It answers whether the flicker has ended. */
function advanceSquare(
  pen: CanvasRenderingContext2D,
  grid: Grid,
  index: number,
  now: number
) {
  const age = now - grid.startsAt[index];
  if (age < 0) {
    return false;
  }
  const progress = Math.min(1, age / FLICKER_MS);
  const eased = smoothstep(0, 1, progress);
  grid.level[index] = towards(grid.from[index], grid.to[index], eased);
  paintSquare(pen, grid, index);
  return progress === 1;
}

/** Only the squares in the middle of a flicker are drawn. One that has ended leaves the list. */
function advanceFlickers(
  pen: CanvasRenderingContext2D,
  grid: Grid,
  now: number
) {
  let slot = 0;
  while (slot < grid.busyCount) {
    const index = grid.busy[slot];
    const hasEnded = advanceSquare(pen, grid, index, now);
    if (hasEnded) {
      const last = grid.busyCount - 1;
      grid.isBusy[index] = 0;
      grid.busy[slot] = grid.busy[last];
      grid.busyCount = last;
    }
    if (!hasEnded) {
      slot += 1;
    }
  }
}

function stepGrid(grid: Grid, surface: Surface, seconds: number, now: number) {
  if (grid.isStill) {
    return AT_REST;
  }
  surface.pen.fillStyle = grid.inks.hue;
  startFlickers(grid, seconds, now);
  advanceFlickers(surface.pen, grid, now);
  return NEXT_FRAME;
}

type FlickerScene = Scene & {
  setWord: (word: string) => void;
};

function createFlickerScene(options: GridOptions): FlickerScene {
  const grid = gridOf(options);
  return {
    ink(inks) {
      grid.inks = inks;
    },
    fit(surface, isStill) {
      layGrid(grid, surface, isStill);
    },
    draw(surface) {
      drawGrid(grid, surface);
    },
    step(surface, seconds, now) {
      return stepGrid(grid, surface, seconds, now);
    },
    setWord(word) {
      const isSameWord = word === grid.word;
      if (isSameWord) {
        return;
      }
      grid.word = word;
      takeWord(grid, performance.now());
    },
  };
}

export type FlickeringGridProps = {
  className?: string;
  /** Any colour token, such as `var(--primary)` or `var(--series-2)`. The squares wear it. */
  hue?: string;
  /** The side of a square, in pixels. */
  size?: number;
  /** The space between two squares, in pixels. */
  gap?: number;
  /** The darkest a square outside the word gets, from 0 to 1. */
  maxOpacity?: number;
  /** A word whose squares sit higher than the rest. It reads by opacity alone. */
  word?: string;
  /** Where the middle of the word sits down the grid, from 0 at the top to 1 at the bottom. */
  wordAt?: number;
};

/**
 * A grid of small squares that flicker under a low ceiling, a few at a time, on one canvas. A word
 * can be set into it: its squares sit higher, and a new word surfaces square by square. Only the
 * squares in the middle of a flicker are drawn. It fills its parent, which must be positioned.
 * Under reduced motion the grid stands still, the word in it.
 */
export function FlickeringGrid({
  className,
  hue = DEFAULT_HUE,
  size = DEFAULT_SQUARE,
  gap = DEFAULT_GAP,
  maxOpacity = DEFAULT_CEILING,
  word = '',
  wordAt = 0.5,
}: FlickeringGridProps) {
  const stage = useRef<StageHandle>(null);
  const scene = useMemo(
    () => createFlickerScene({ size, gap, maxOpacity, wordAt }),
    [size, gap, maxOpacity, wordAt]
  );

  useEffect(() => {
    scene.setWord(word);
    stage.current?.refresh();
  }, [scene, word]);

  return (
    <StageCanvas
      handleRef={stage}
      scene={scene}
      hue={hue}
      className={className}
    />
  );
}

const WORDS = ['ndeko', 'quiet', 'fields'];

/** The word sits above the middle of the band, clear of the headline at its foot. */
const WORD_AT = 0.38;

const WORD_HOLD_MS = 3600;

export default function Background05() {
  const [round, setRound] = useState(0);
  const { pressed, press } = usePress<'next'>();
  const word = WORDS[round % WORDS.length];

  function showNextWord() {
    setRound((current) => current + 1);
  }

  const steps: AutoplayStep[] = [
    { after: WORD_HOLD_MS, run: () => press('next') },
    { after: PRESS_LEAD_MS, run: showNextWord },
  ];
  const { ref } = useAutoplay<HTMLElement>(steps, { loopAfter: 0 });

  return (
    <DemoBand
      ref={ref}
      align='end'
      title='A word surfaces from the grid'
      background={<FlickeringGrid word={word} wordAt={WORD_AT} />}
    >
      <Button
        onClick={showNextWord}
        className={pressedSolidOf(pressed === 'next')}
      >
        Next word
      </Button>
    </DemoBand>
  );
}

import { useId, type ReactNode, type Ref } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

type BandAlign = 'center' | 'end';

const ALIGNMENTS: Record<BandAlign, string> = {
  center: 'justify-center',
  end: 'justify-end pb-10',
};

type DemoBandProps = {
  ref?: Ref<HTMLElement>;
  title: string;
  /** The background under test. It fills the band, behind the headline and the actions. */
  background: ReactNode;
  /** `end` sets the headline at the foot of the band and leaves its middle to the background. */
  align?: BandAlign;
  children: ReactNode;
};

/**
 * The band every background is shown in: the page colour, a headline in the foreground colour and
 * the actions laid straight over the background, to prove that text stays readable above it.
 */
export function DemoBand({
  ref,
  title,
  background,
  align = 'center',
  children,
}: DemoBandProps) {
  const titleId = useId();

  return (
    <section
      ref={ref}
      aria-labelledby={titleId}
      className={cn(
        'bg-background @container relative isolate flex h-90 w-full flex-col items-center overflow-hidden rounded-xl',
        ALIGNMENTS[align]
      )}
    >
      {background}
      <div className='relative flex max-w-lg flex-col items-center gap-5 px-6 text-center'>
        <h3
          id={titleId}
          className='text-2xl font-semibold text-balance @lg:text-3xl'
        >
          {title}
        </h3>
        <div className='flex flex-wrap items-center justify-center gap-2'>
          {children}
        </div>
      </div>
    </section>
  );
}

const FRAMES_PER_SECOND = 30;

const FRAME_MS = 1000 / FRAMES_PER_SECOND;

/**
 * The timer between two frames ends this long before the next one is due, so the frame it asks for
 * lands on the screen refresh that is due and not on the one after.
 */
const REFRESH_LEAD_MS = 5;

const TIMER_MS = FRAME_MS - REFRESH_LEAD_MS;

/** A frame that comes late, after a long task, moves the picture no further than this long would. */
const MAX_STEP_S = 0.05;

/** What a frame answers while the picture still moves: the next one comes as soon as the cap allows. */
export const NEXT_FRAME = 0;

/** What a frame answers once the picture has come to rest: nothing is asked for until `wake`. */
export const AT_REST = Number.POSITIVE_INFINITY;

/** Draws one frame, `seconds` after the last one, and answers how many milliseconds it can wait for the next. */
export type FrameHandler = (seconds: number, now: number) => number;

export type FrameLoop = {
  start: () => void;
  stop: () => void;
  wake: () => void;
};

/**
 * Frames at thirty a second at most. Between two frames there is one timer and no animation frame,
 * so a 120 Hz screen does not run four rounds of main-thread work for one frame drawn. Stopped or
 * at rest, the loop holds no timer and asks for no frame.
 */
export function createFrameLoop(onFrame: FrameHandler): FrameLoop {
  let frame = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let isStarted = false;
  let lastFrameAt = 0;

  function clearPending() {
    cancelAnimationFrame(frame);
    clearTimeout(timer);
    frame = 0;
    timer = undefined;
  }

  function askForFrame() {
    timer = undefined;
    frame = requestAnimationFrame(tick);
  }

  function schedule(wait: number) {
    clearPending();
    const now = performance.now();
    const sinceFrame = now - lastFrameAt;
    const untilCap = TIMER_MS - sinceFrame;
    const delay = Math.max(wait, untilCap);
    if (delay <= 0) {
      askForFrame();
      return;
    }
    timer = setTimeout(askForFrame, delay);
  }

  function tick(now: number) {
    frame = 0;
    const elapsedMs = now - lastFrameAt;
    const elapsed = elapsedMs / 1000;
    const forward = Math.max(0, elapsed);
    const seconds = Math.min(forward, MAX_STEP_S);
    lastFrameAt = now;
    const wait = onFrame(seconds, now);
    const isResting = wait === AT_REST;
    if (isResting || !isStarted) {
      return;
    }
    schedule(wait);
  }

  function start() {
    if (isStarted) {
      return;
    }
    const now = performance.now();
    isStarted = true;
    lastFrameAt = now - FRAME_MS;
    schedule(NEXT_FRAME);
  }

  function stop() {
    isStarted = false;
    clearPending();
  }

  function wake() {
    const isFrameComing = frame !== 0;
    if (!isStarted || isFrameComing) {
      return;
    }
    schedule(NEXT_FRAME);
  }

  return { start, stop, wake };
}

'use client';

import { useState } from 'react';

/** A background wears one hue: the brand unless it is told otherwise. */
export const DEFAULT_HUE = 'var(--primary)';

/** The brand first, then the series hues that differ from it. */
const DEMO_HUES = [
  DEFAULT_HUE,
  'var(--series-2)',
  'var(--series-3)',
  'var(--series-4)',
  'var(--series-5)',
];

/** The hue of a demo, and the step to the next one, to show a background in each hue it accepts. */
export function useHueCycle() {
  const [index, setIndex] = useState(0);
  const hue = DEMO_HUES[index] ?? DEFAULT_HUE;

  function nextHue() {
    setIndex((current) => {
      const next = current + 1;
      return next % DEMO_HUES.length;
    });
  }

  return { hue, nextHue };
}

export type Point = {
  x: number;
  y: number;
};

export function clamp(value: number, low: number, high: number) {
  const raised = Math.max(low, value);
  return Math.min(high, raised);
}

/** How much of the way left is covered in `seconds`: the same glide whatever the frame rate. */
export function shareOf(seconds: number, easeSeconds: number) {
  const ratio = seconds / easeSeconds;
  const decay = Math.exp(-ratio);
  return 1 - decay;
}

export function towards(from: number, to: number, share: number) {
  const gap = to - from;
  const step = gap * share;
  return from + step;
}

/** From 0 at `low` to 1 at `high`, leaving and arriving without a corner. */
export function smoothstep(low: number, high: number, value: number) {
  const span = high - low;
  const offset = value - low;
  const raw = offset / span;
  const share = clamp(raw, 0, 1);
  const doubled = 2 * share;
  const curve = 3 - doubled;
  const squared = share * share;
  return squared * curve;
}

/** The damping that brings a spring of this stiffness to its target without passing it. */
export function dampingOf(stiffness: number) {
  const root = Math.sqrt(stiffness);
  return 2 * root;
}

/**
 * The speed of a spring one step later. The caller then moves the value by that speed over the
 * same step, so the value follows its target and settles on it.
 */
export function springSpeedOf(
  gap: number,
  speed: number,
  stiffness: number,
  damping: number,
  seconds: number
) {
  const pull = gap * stiffness;
  const drag = speed * damping;
  const push = pull - drag;
  const gain = push * seconds;
  return speed + gain;
}

import type { Point } from './math';

/**
 * Where a point of the window falls inside `host`, in the pixels of its own box, or null when it
 * falls outside. A host that an ancestor scales still answers in its own pixels.
 */
export function placeIn(
  host: HTMLElement,
  clientX: number,
  clientY: number
): Point | null {
  const box = host.getBoundingClientRect();
  const isEmpty = box.width === 0 || box.height === 0;
  if (isEmpty) {
    return null;
  }
  const isInsideX = clientX >= box.left && clientX <= box.right;
  const isInsideY = clientY >= box.top && clientY <= box.bottom;
  if (!isInsideX || !isInsideY) {
    return null;
  }
  const scaleX = host.offsetWidth / box.width;
  const scaleY = host.offsetHeight / box.height;
  const offsetX = clientX - box.left;
  const offsetY = clientY - box.top;
  const x = offsetX * scaleX;
  const y = offsetY * scaleY;
  return { x, y };
}

/** Where the centre of `element` falls inside `host`, or null when it falls outside. */
export function centreIn(host: HTMLElement, element: Element) {
  const box = element.getBoundingClientRect();
  const halfWidth = box.width / 2;
  const halfHeight = box.height / 2;
  const centreX = box.left + halfWidth;
  const centreY = box.top + halfHeight;
  return placeIn(host, centreX, centreY);
}

/**
 * Follows a pointer that can hover, from the window: content laid over a background takes the
 * pointer events of its own box, so a listener on the background would go blind under a headline.
 * The place is read once a frame at most, and only on a frame where the pointer moved. `onMove`
 * gets the place inside `host`; `onLeave` is called once when the pointer goes out of it. The
 * function returned ends the watch, and lets go of a pointer that was still over the host.
 */
export function watchPointer(
  host: HTMLElement,
  onMove: (x: number, y: number) => void,
  onLeave: () => void
) {
  let clientX = 0;
  let clientY = 0;
  let frame = 0;
  let isOver = false;

  function leave() {
    if (!isOver) {
      return;
    }
    isOver = false;
    onLeave();
  }

  function read() {
    frame = 0;
    const place = placeIn(host, clientX, clientY);
    if (!place) {
      leave();
      return;
    }
    isOver = true;
    onMove(place.x, place.y);
  }

  function onPointerMove(event: PointerEvent) {
    const isTouch = event.pointerType === 'touch';
    if (isTouch) {
      return;
    }
    clientX = event.clientX;
    clientY = event.clientY;
    const isReadComing = frame !== 0;
    if (isReadComing) {
      return;
    }
    frame = requestAnimationFrame(read);
  }

  function onPointerGone() {
    cancelAnimationFrame(frame);
    frame = 0;
    leave();
  }

  const root = document.documentElement;
  window.addEventListener('pointermove', onPointerMove, { passive: true });
  root.addEventListener('pointerleave', onPointerGone, { passive: true });

  return () => {
    window.removeEventListener('pointermove', onPointerMove);
    root.removeEventListener('pointerleave', onPointerGone);
    onPointerGone();
  };
}

const STREAM_STEP = 0x6d2b79f5;

const UINT32_RANGE = 4294967296;

const FIRST_PRIME = 73856093;

const SECOND_PRIME = 19349663;

/**
 * A stream of numbers from 0 to 1, the same for the same seed on the server and in the browser, so
 * a generated picture never changes between two renders.
 */
export function randomOf(seed: number) {
  let state = seed >>> 0;

  function next() {
    const stepped = state + STREAM_STEP;
    state = stepped >>> 0;
    const shifted = state >>> 15;
    const folded = state ^ shifted;
    const odd = state | 1;
    const first = Math.imul(folded, odd);
    const reshifted = first >>> 7;
    const refolded = first ^ reshifted;
    const salted = first | 61;
    const second = Math.imul(refolded, salted);
    const summed = first + second;
    const mixed = first ^ summed;
    const lastShift = mixed >>> 14;
    const settled = mixed ^ lastShift;
    const positive = settled >>> 0;
    return positive / UINT32_RANGE;
  }

  return next;
}

/** One seed out of two numbers, so each part of a picture draws from a stream of its own. */
export function seedOf(first: number, second: number) {
  const firstHash = Math.imul(first, FIRST_PRIME);
  const secondHash = Math.imul(second, SECOND_PRIME);
  const mixed = firstHash ^ secondHash;
  return mixed >>> 0;
}

/**
 * A background sits behind content for as long as the page is open, so everything it runs hangs on
 * this answer: its box touches the screen and the tab is the one looked at. `onChange` is called
 * each time the answer changes, starting from "not showing". The function returned ends the watch.
 */
export function watchShowing(
  element: Element,
  onChange: (isShowing: boolean) => void
) {
  let isOnScreen = false;
  let wasShowing = false;

  function report() {
    const isTabShown = document.visibilityState === 'visible';
    const isShowing = isOnScreen && isTabShown;
    if (isShowing === wasShowing) {
      return;
    }
    wasShowing = isShowing;
    onChange(isShowing);
  }

  function onCrossing(entries: IntersectionObserverEntry[]) {
    const latest = entries.at(-1);
    if (!latest) {
      return;
    }
    isOnScreen = latest.isIntersecting;
    report();
  }

  const observer = new IntersectionObserver(onCrossing);
  observer.observe(element);
  document.addEventListener('visibilitychange', report);

  return () => {
    observer.disconnect();
    document.removeEventListener('visibilitychange', report);
  };
}

'use client';

import { useEffect, useImperativeHandle, useRef, type Ref } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

import type { Point } from './math';
import { mountStage, type Scene, type Stage } from './stage';

export type StageHandle = {
  /** Something outside the loop changed the scene: it is drawn again, and its loop is woken. */
  refresh: () => void;
  /** Where the centre of an element sits on the canvas, or null when it is outside. */
  centreOf: (element: Element) => Point | null;
};

type StageCanvasProps = {
  scene: Scene;
  hue: string;
  isInteractive?: boolean;
  className?: string;
  handleRef?: Ref<StageHandle>;
};

/**
 * The one canvas of a background. It fills its parent, lets every pointer event through and is
 * hidden from assistive technology, since it is decoration. A canvas cannot take a colour from a
 * class: the hue rides on its `color` and the neutral of lines on `decoration-foreground`, and the
 * stage reads both from the computed style. No transition may sit on those two, or the stage
 * would read a colour halfway through it.
 */
export function StageCanvas({
  scene,
  hue,
  isInteractive = false,
  className,
  handleRef,
}: StageCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const stage = useRef<Stage | null>(null);
  const shouldReduceMotion = usePrefersReducedMotion();

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const mounted = mountStage(canvas, scene, {
      isStill: shouldReduceMotion,
      isInteractive,
    });
    stage.current = mounted;
    return () => {
      mounted?.dispose();
      stage.current = null;
    };
  }, [scene, isInteractive, shouldReduceMotion]);

  useEffect(() => {
    stage.current?.reink();
  }, [hue]);

  useImperativeHandle(
    handleRef,
    () => ({
      refresh: () => stage.current?.refresh(),
      centreOf: (element) => stage.current?.centreOf(element) ?? null,
    }),
    []
  );

  return (
    <canvas
      ref={canvasRef}
      aria-hidden='true'
      style={{ color: hue }}
      className={cn(
        'decoration-foreground pointer-events-none absolute inset-0 size-full',
        className
      )}
    />
  );
}

import { createFrameLoop } from './frame-loop';
import type { Point } from './math';
import { centreIn, watchPointer } from './pointer';
import { watchShowing } from './showing';
import {
  createSurface,
  fitSurface,
  hasSameInks,
  inksOf,
  isFitted,
  watchSurface,
  type Inks,
  type Surface,
} from './surface';

/** What a background draws on its canvas. The stage decides when; the scene only knows how. */
export type Scene = {
  /** The colours changed: the theme, or the hue. */
  ink: (inks: Inks) => void;
  /**
   * The box changed, and the canvas was wiped: what depends on its size is built again. `isStill`
   * is the reduced motion setting: the scene then holds its most telling picture and never moves.
   */
  fit: (surface: Surface, isStill: boolean) => void;
  /** The whole picture as it stands. */
  draw: (surface: Surface) => void;
  /**
   * Moves the picture on by `seconds` and draws what changed. It answers how long it can wait for
   * its next frame: `NEXT_FRAME`, `AT_REST`, or a number of milliseconds.
   */
  step: (surface: Surface, seconds: number, now: number) => number;
  pointerMoved?: (x: number, y: number) => void;
  pointerLeft?: () => void;
};

export type Stage = {
  /** Something outside the loop changed the scene: it is drawn again, and its loop is woken. */
  refresh: () => void;
  /** Reads the colours again, and draws again when they changed. */
  reink: () => void;
  /** Where the centre of an element sits on the canvas, or null when it is outside. */
  centreOf: (element: Element) => Point | null;
  dispose: () => void;
};

export type StageOptions = {
  /** Reduced motion: no pointer is followed and nothing moves by itself. */
  isStill: boolean;
  isInteractive: boolean;
};

function idle() {}

function stageOf(
  surface: Surface,
  scene: Scene,
  { isStill, isInteractive }: StageOptions
): Stage {
  const { canvas } = surface;
  const followsPointer = isInteractive && !isStill;
  let isShowing = false;
  let stopPointer = idle;
  let inks = inksOf(canvas);

  const loop = createFrameLoop((seconds, now) =>
    scene.step(surface, seconds, now)
  );

  function wake() {
    if (isShowing) {
      loop.wake();
    }
  }

  function lay() {
    fitSurface(surface);
    scene.fit(surface, isStill);
    scene.draw(surface);
  }

  function onPointerMove(x: number, y: number) {
    scene.pointerMoved?.(x, y);
    wake();
  }

  function onPointerLeave() {
    scene.pointerLeft?.();
    wake();
  }

  function show() {
    isShowing = true;
    if (followsPointer) {
      stopPointer = watchPointer(canvas, onPointerMove, onPointerLeave);
    }
    loop.start();
  }

  function hide() {
    isShowing = false;
    stopPointer();
    stopPointer = idle;
    loop.stop();
  }

  function onShowing(isNowShowing: boolean) {
    if (isNowShowing) {
      show();
      return;
    }
    hide();
  }

  function onResize() {
    if (isFitted(surface)) {
      return;
    }
    lay();
    wake();
  }

  function reink() {
    const latest = inksOf(canvas);
    if (hasSameInks(inks, latest)) {
      return;
    }
    inks = latest;
    scene.ink(inks);
    scene.draw(surface);
    wake();
  }

  /** In the loop, the next frame draws the change. Out of it, nothing would, so it is drawn here. */
  function refresh() {
    const isOutOfLoop = isStill || !isShowing;
    if (isOutOfLoop) {
      scene.draw(surface);
    }
    wake();
  }

  scene.ink(inks);
  lay();
  const stopSurface = watchSurface(canvas, onResize, reink);
  const stopShowing = watchShowing(canvas, onShowing);

  return {
    refresh,
    reink,
    centreOf: (element) => centreIn(canvas, element),
    dispose() {
      stopShowing();
      stopSurface();
      hide();
    },
  };
}

/**
 * Puts a scene on a canvas. The stage sizes the canvas for the screen, reads its colours, and runs
 * the loop of the scene only while the canvas is on screen in a visible tab. It draws one frame
 * when it is set up, so the picture is there before anything moves.
 */
export function mountStage(
  canvas: HTMLCanvasElement,
  scene: Scene,
  options: StageOptions
) {
  const surface = createSurface(canvas);
  if (!surface) {
    return null;
  }
  return stageOf(surface, scene, options);
}

/** A backing store above two device pixels a point costs four times the fill for a picture nobody sees sharper. */
const MAX_PIXEL_RATIO = 2;

const THEME_WATCH = {
  attributes: true,
  attributeFilter: ['class', 'data-theme'],
};

const DARK_SCHEME = '(prefers-color-scheme: dark)';

export type Surface = {
  canvas: HTMLCanvasElement;
  pen: CanvasRenderingContext2D;
  /** The box of the canvas in CSS pixels: one unit drawn is one of them, whatever the screen. */
  width: number;
  height: number;
  pixelRatio: number;
};

export type Inks = {
  /** The hue of the background, resolved by the browser for the current theme. */
  hue: string;
  /** The neutral of lines: the foreground of the theme. */
  line: string;
};

export function createSurface(canvas: HTMLCanvasElement): Surface | null {
  const pen = canvas.getContext('2d');
  if (!pen) {
    return null;
  }
  return { canvas, pen, width: 0, height: 0, pixelRatio: 1 };
}

function pixelRatioOf() {
  const devicePixelRatio = window.devicePixelRatio || 1;
  return Math.min(devicePixelRatio, MAX_PIXEL_RATIO);
}

/** Sizes the backing store to the box of the canvas and to the screen. It also wipes the canvas. */
export function fitSurface(surface: Surface) {
  const { canvas, pen } = surface;
  const pixelRatio = pixelRatioOf();
  const width = canvas.clientWidth;
  const height = canvas.clientHeight;
  const deviceWidth = width * pixelRatio;
  const deviceHeight = height * pixelRatio;
  surface.width = width;
  surface.height = height;
  surface.pixelRatio = pixelRatio;
  canvas.width = Math.round(deviceWidth);
  canvas.height = Math.round(deviceHeight);
  pen.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
}

export function isFitted(surface: Surface) {
  const { canvas } = surface;
  const hasWidth = surface.width === canvas.clientWidth;
  const hasHeight = surface.height === canvas.clientHeight;
  const hasRatio = surface.pixelRatio === pixelRatioOf();
  const hasSize = hasWidth && hasHeight;
  return hasSize && hasRatio;
}

export function wipeSurface(surface: Surface) {
  surface.pen.globalAlpha = 1;
  surface.pen.clearRect(0, 0, surface.width, surface.height);
}

/**
 * A canvas cannot take a colour from a class, so it reads its colours from its own computed style,
 * where the browser has already resolved the tokens for the current theme. The hue rides on
 * `color` and the neutral of lines on `text-decoration-color`, which paints nothing on a canvas.
 */
export function inksOf(canvas: HTMLCanvasElement): Inks {
  const style = getComputedStyle(canvas);
  return { hue: style.color, line: style.textDecorationColor };
}

export function hasSameInks(first: Inks, second: Inks) {
  const hasSameHue = first.hue === second.hue;
  const hasSameLine = first.line === second.line;
  return hasSameHue && hasSameLine;
}

function densityQueryOf() {
  return `(resolution: ${window.devicePixelRatio}dppx)`;
}

/**
 * Calls `onResize` when the box of the canvas or the density of the screen changes, and `onTheme`
 * when the page may have changed theme: a class or an attribute on the root or the body, or the
 * system setting. The function returned ends the watch.
 */
export function watchSurface(
  canvas: HTMLCanvasElement,
  onResize: () => void,
  onTheme: () => void
) {
  const sizeObserver = new ResizeObserver(() => onResize());
  const themeObserver = new MutationObserver(() => onTheme());
  const scheme = window.matchMedia(DARK_SCHEME);
  let density = window.matchMedia(densityQueryOf());

  function onScheme() {
    onTheme();
  }

  /** The query names one density: once the screen has left it, a new query watches the next one. */
  function onDensity() {
    density.removeEventListener('change', onDensity);
    density = window.matchMedia(densityQueryOf());
    density.addEventListener('change', onDensity);
    onResize();
  }

  sizeObserver.observe(canvas);
  themeObserver.observe(document.documentElement, THEME_WATCH);
  themeObserver.observe(document.body, THEME_WATCH);
  scheme.addEventListener('change', onScheme);
  density.addEventListener('change', onDensity);

  return () => {
    sizeObserver.disconnect();
    themeObserver.disconnect();
    scheme.removeEventListener('change', onScheme);
    density.removeEventListener('change', onDensity);
  };
}
